<script>
const c=document.getElementById('c'),ctx=c.getContext('2d'),shape=document.getElementById('shape');
let start=null;
c.onmousedown=e=>{start={x:e.offsetX,y:e.offsetY};};
c.onmouseup=e=>{
  if(!start)return;
  const x=start.x, y=start.y, x2=e.offsetX, y2=e.offsetY;
  ctx.beginPath();
  if(shape.value==='line'){
    ctx.moveTo(x,y);ctx.lineTo(x2,y2);
  }else{
    ctx.rect(x,y,x2-x,y2-y);
  }
  ctx.stroke();
  start=null;
};
</script>
</body>
</html>
