<!DOCTYPE html>
<html>
<head>
  <meta charset='UTF-8'>
  <title>Recent Colors</title>
  <style>
    body{font-family:sans-serif;text-align:center;margin-top:30px;}
    .swatch{display:inline-block;width:30px;height:30px;margin:5px;border:1px solid #000;cursor:pointer;}
  </style>
</head>
<body>
  <input type='color' id='picker'>
  <div id='history'></div>
  <script>
    const cp=document.getElementById('picker');
    const hist=document.getElementById('history');
    const colors=[];
    function render(){
      hist.innerHTML='';
      colors.forEach(c=>{
        const div=document.createElement('div');
        div.className='swatch';
        div.style.backgroundColor=c;
        div.onclick=()=>document.body.style.backgroundColor=c;
        hist.appendChild(div);
      });
    }
    cp.addEventListener('input',()=>{
      const col=cp.value;
      document.body.style.backgroundColor=col;
      colors.unshift(col);
      if(colors.length>3) colors.pop();
      render();
    });
  </script>
</body>
</html>
